// We use Verus to verify that this implementation of binary search
// correctly decides whether k appears in a non‐decreasing slice of ints.
verus! {

    /// Returns `true` iff there is some index i with 0 <= i < a.len() and a[i] == k.
    /// Precondition: `a` is sorted non‐decreasingly.
    pub fn bin_search(a: &[int], k: int) -> (b: bool)
        // sortedness precondition
        requires(
            forall|i: int, j: int|
                0 <= i && i <= j && j < a.len() as int
                ==>
                a[i as usize] <= a[j as usize]
        )
        // postcondition says b iff there exists an index with a[i] == k
        ensures(
            b <==>
            exists|i: int| 0 <= i && i < a.len() as int && a[i as usize] == k
        )
    {
        let mut lo: int = 0;
        let mut hi: int = a.len() as int;
        // We maintain the invariants:
        //  0 <= lo <= hi <= a.len()
        //  for all i < lo, a[i] < k
        //  for all i >= hi, a[i] > k
        // And we decrease (hi - lo) each iteration.
        while lo < hi
            invariant 0 <= lo && lo <= hi && hi <= a.len() as int
            invariant forall|i: int| 0 <= i && i < lo ==> a[i as usize] < k
            invariant forall|i: int| hi <= i && i < a.len() as int ==> a[i as usize] > k
            decreases hi - lo
        {
            let mid: int = lo + (hi - lo) / 2;
            // mid is in [lo, hi), hence 0 <= mid < a.len()
            assert(lo <= mid && mid < hi && hi <= a.len() as int);
            let mid_usize: usize = mid as usize;
            if a[mid_usize] < k {
                // Everything below and including mid is < k,
                // so we can safely move lo up.
                lo = mid + 1;
            } else if a[mid_usize] > k {
                // Everything at or above mid is > k,
                // so we can safely move hi down.
                hi = mid;
            } else {
                // Found k!
                return (true);
            }
        }

        // When the loop exits, lo == hi, and by the invariants:
        //  for all i < lo, a[i] < k
        //  for all i >= lo, a[i] > k
        // so no element is equal to k.
        false
    }
}